use speedyspec_wp_theme_json::{MemoryGlobalSettings, NoTranslation, RecordedDiagnostics};
use support::{assert_php_same as assert_php_eq, json, php_list};

struct Harness {
    fluid: FluidFontSize,
    notices: Rc<RecordedDiagnostics>,
}

impl Harness {
    fn new(global: Value) -> Harness {
        let notices = Rc::new(RecordedDiagnostics::default());
        Harness {
            fluid: FluidFontSize {
                global: Rc::new(MemoryGlobalSettings::new(global)),
                diagnostics: notices.clone(),
            },
            notices,
        }
    }
    fn ctx(&self) -> DeclarationContext<'_> {
        DeclarationContext {
            fluid: &self.fluid,
            diagnostics: &*self.notices,
            gettext: &NoTranslation,
        }
    }
    fn notices(&self) -> Vec<String> {
        self.notices.notices.borrow().clone()
    }
}

fn pair(data: Value, notices: Vec<String>) -> Value {
    php_list(vec![
        data,
        php_list(notices.into_iter().map(Value::Str).collect()),
    ])
}

fn decls(list: Vec<Declaration>) -> Value {
    php_list(
        list.into_iter()
            .map(|d| {
                Value::Array(vec![
                    (Key::Str("name".into()), Value::Str(d.name)),
                    (Key::Str("value".into()), d.value),
                ])
            })
            .collect(),
    )
}

fn fdecls(list: FeatureDeclarations) -> Value {
    Value::Array(
        list.into_iter()
            .map(|(s, d)| (Key::Str(s), decls(d)))
            .collect(),
    )
}

fn from_decls(value: &Value) -> Vec<Declaration> {
    let Value::Array(items) = value else {
        return Vec::new();
    };
    items
        .iter()
        .map(|(_, d)| {
            let get = |k: &str| match d {
                Value::Array(e) => e
                    .iter()
                    .find(|(key, _)| *key == Key::Str(k.into()))
                    .map(|(_, v)| v.clone())
                    .unwrap_or(Value::Null),
                _ => Value::Null,
            };
            let Value::Str(name) = get("name") else {
                panic!("name")
            };
            Declaration::new(name, get("value"))
        })
        .collect()
}

fn from_fdecls(value: &Value) -> FeatureDeclarations {
    let Value::Array(items) = value else {
        return Vec::new();
    };
    items
        .iter()
        .map(|(k, v)| {
            (
                match k {
                    Key::Str(s) => s.clone(),
                    Key::Int(i) => i.to_string(),
                },
                from_decls(v),
            )
        })
        .collect()
}

